def is_sorted(lst):
    '''
    Given a list of numbers, return whether or not they are sorted
    in ascending order. If list has more than 1 duplicate of the same
    number, return False. Assume no negative numbers and only integers.

    Examples
    is_sorted([5]) ➞ True
    is_sorted([1, 2, 3, 4, 5]) ➞ True
    is_sorted([1, 3, 2, 4, 5]) ➞ False
    is_sorted([1, 2, 3, 4, 5, 6]) ➞ True
    is_sorted([1, 2, 3, 4, 5, 6, 7]) ➞ True
    is_sorted([1, 3, 2, 4, 5, 6, 7]) ➞ False
    is_sorted([1, 2, 2, 3, 3, 4]) ➞ True
    is_sorted([1, 2, 2, 2, 3, 4]) ➞ False
    '''
    if len(lst) <= 1:
        return True

    for i in range(len(lst) - 1):
        if lst[i] > lst[i+1]:
            return False
        if i > 0 and lst[i] == lst[i-1] and lst[i] == lst[i+1]:
            return False
        if i == 0 and lst[i] == lst[i+1] and len(lst) > 2 and lst[i+1] == lst[i+2]:
            return False
        if i > 0 and lst[i] == lst[i+1] and lst[i-1] == lst[i] and lst[i+1] == lst[i+2]:
            return False

    # Check for more than one duplicate of the same number
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] > 2:
            return False

    return True

